python3 << 'PYEOF'
from pptx import Presentation
from pptx.util import Inches

prs = Presentation("/app/output/final_deck.pptx")
print(f"Slide dimensions: {prs.slide_width} x {prs.slide_height}")
print(f"  => {prs.slide_width / 914400:.2f}\" x {prs.slide_height / 914400:.2f}\"")
print(f"Total slides: {len(prs.slides)}\n")

for i, slide in enumerate(prs.slides):
    print(f"=== SLIDE {i+1} ===")
    texts = []
    table_count = 0
    for shape in slide.shapes:
        if shape.has_table:
            table_count += 1
            t = shape.table
            print(f"  TABLE: {t.rows.__len__()} rows x {len(t.columns)} cols")
            for r in range(min(2, len(t.rows))):
                row_text = [t.cell(r, c).text for c in range(len(t.columns))]
                print(f"    Row {r}: {row_text}")
        elif shape.has_text_frame:
            for p in shape.text_frame.paragraphs:
                if p.text.strip():
                    texts.append(p.text.strip()[:80])
    for t in texts[:5]:
        print(f"  {t}")
    if len(texts) > 5:
        print(f"  ... +{len(texts)-5} more text elements")
    if table_count:
        print(f"  Tables on slide: {table_count}")
    print()
PYEOF

